/**
 * Клиент Green API: единая очередь с ограничением частоты и осторожными
 * повторами. Прямые fetch из бизнес-логики запрещены (§5).
 *
 * Главное отличие от чтения: отправку нельзя повторять вслепую. Если запрос
 * оборвался на таймауте, сообщение могло уйти — и повтор пришлёт пациенту
 * второе. Поэтому повторяем только явные «подожди» и отказы до обработки.
 */

export interface WhatsappCredentials {
  idInstance: string;
  apiToken: string;
}

export interface SendResult {
  ok: boolean;
  /** Идентификатор сообщения у провайдера — для идемпотентности и статусов. */
  externalId?: string;
  /** Причина, понятная человеку: она попадёт на экран администратору. */
  error?: string;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

let chain: Promise<unknown> = Promise.resolve();
let lastAt = 0;

function enqueue<T>(task: () => Promise<T>): Promise<T> {
  const run = chain.then(async () => {
    const wait = RATE_LIMIT.minIntervalMs - (Date.now() - lastAt);
    if (wait > 0) await sleep(wait);
    try {
      return await task();
    } finally {
      lastAt = Date.now();
    }
  });
  chain = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

export async function loadCredentials(companyId: string): Promise<WhatsappCredentials | null> {
  const rows = await prisma.credential.findMany({
    where: { companyId, provider: WHATSAPP_PROVIDER },
    select: { keyName: true, valueEncrypted: true },
  });
  const byKey = new Map(rows.map((r) => [r.keyName, r.valueEncrypted]));
  const id = byKey.get("id_instance");
  const token = byKey.get("api_token");
  if (!id || !token) return null;
  try {
    return { idInstance: decryptSecret(id), apiToken: decryptSecret(token) };
  } catch {
    // Сменившийся мастер-ключ или повреждённый шифртекст — считаем ненастроенным.
    return null;
  }
}

async function call<T>(
  path: string,
  body?: unknown,
): Promise<{ ok: true; data: T } | { ok: false; error: string; status: number }> {
  const url = `${GREEN_API_BASE}${path}`;
  const isWrite = body !== undefined;
  let attempt = 0;

  for (;;) {
    let res: Response;
    try {
      res = await fetch(url, {
        method: isWrite ? "POST" : "GET",
        headers: isWrite ? { "Content-Type": "application/json" } : {},
        body: isWrite ? JSON.stringify(body) : undefined,
        // Провайдер иногда отвечает долго; без предела запрос повиснет и
        // займёт соединение до бесконечности.
        signal: AbortSignal.timeout(20_000),
      });
    } catch (e) {
      const message = (e as Error).name === "TimeoutError" ? "провайдер не ответил вовремя" : "сеть недоступна";
      // Отправку на обрыве не повторяем: сообщение могло уйти, и повтор
      // пришлёт пациенту второе.
      if (isWrite || attempt >= RATE_LIMIT.maxRetries) return { ok: false, error: message, status: 0 };
      await sleep(RATE_LIMIT.baseDelayMs * 2 ** attempt);
      attempt += 1;
      continue;
    }

    // 429 — провайдер прямо просит подождать и заведомо ничего не выполнил.
    if (res.status === 429 && attempt < RATE_LIMIT.maxRetries) {
      await sleep(RATE_LIMIT.baseDelayMs * 2 ** attempt);
      attempt += 1;
      continue;
    }
    if (!isWrite && res.status >= 500 && attempt < RATE_LIMIT.maxRetries) {
      await sleep(RATE_LIMIT.baseDelayMs * 2 ** attempt);
      attempt += 1;
      continue;
    }

    if (!res.ok) {
      const text = await res.text().catch(() => "");
      return { ok: false, status: res.status, error: describeError(res.status, text) };
    }
    return { ok: true, data: (await res.json()) as T };
  }
}

/** Человеческое объяснение вместо кода ответа: его увидит администратор. */
function describeError(status: number, body: string): string {
  if (status === 401 || status === 403) return "неверные ключи Green API";
  if (status === 466) return "исчерпан лимит тарифа Green API";
  if (status === 400 && /not.*whatsapp|no.*account/i.test(body)) {
    return "у этого номера нет WhatsApp";
  }
  return `Green API ответил ${status}${body ? `: ${body.slice(0, 120)}` : ""}`;
}

/**
 * Состояние инстанса. Отправлять можно только из authorized — остальные
 * состояния сообщаем словами, чтобы «сообщение не ушло» не было загадкой.
 */
export async function instanceState(companyId: string): Promise<{ state: string; hint: string } | null> {
  if (!isWhatsappEnabled()) return null;
  const creds = await loadCredentials(companyId);
  if (!creds) return null;

  const res = await enqueue(() =>
    call<{ stateInstance?: string }>(ENDPOINTS.getStateInstance(creds.idInstance, creds.apiToken)),
  );
  if (!res.ok) return { state: "unknown", hint: res.error };
  const state = res.data.stateInstance ?? "unknown";
  return { state, hint: STATE_HINT[state] ?? state };
}

/**
 * Отправить текст пациенту.
 *
 * Адресуем по телефону, а не по chatId из переписки: телефон — наш ключ
 * пациента (§4), и он же остаётся верным, если провайдер сменится.
 */
/**
 * Есть ли WhatsApp у номера.
 *
 * Нужно ровно для одного вопроса: «отправили, а человек не видит». Отправка
 * сама по себе на него не отвечает — Green API принимает сообщение на любой
 * номер и возвращает идентификатор, а доходит оно только туда, где WhatsApp
 * есть. Без этой проверки отличить «не дошло» от «не смотрел» нечем.
 */
export async function numberHasWhatsapp(
  companyId: string,
  phone: string,
): Promise<{ ok: boolean; exists?: boolean; error?: string }> {
  if (!isWhatsappEnabled()) return { ok: false, error: "Интеграция WhatsApp выключена" };
  const creds = await loadCredentials(companyId);
  if (!creds) return { ok: false, error: "Не заданы ключи Green API" };

  const chatId = phone.includes("@") ? phone : chatIdFromPhone(phone);
  if (!chatId) return { ok: false, error: "Не удалось разобрать номер" };
  // Провайдер ждёт голый номер, без «@c.us».
  const digits = chatId.split("@")[0];

  const res = await enqueue(() =>
    call<{ existsWhatsapp?: boolean }>(
      ENDPOINTS.checkWhatsapp(creds.idInstance, creds.apiToken),
      { phoneNumber: Number(digits) },
    ),
  );
  if (!res.ok) return { ok: false, error: res.error };
  return { ok: true, exists: res.data.existsWhatsapp === true };
}

export async function sendText(
  companyId: string,
  phoneOrChatId: string,
  text: string,
): Promise<SendResult> {
  if (!isWhatsappEnabled()) return { ok: false, error: "Интеграция WhatsApp выключена" };

  const creds = await loadCredentials(companyId);
  if (!creds) return { ok: false, error: "Не заданы ключи Green API" };

  // На вход принимаем и телефон, и готовый chatId: диалог хранит chatId, а
  // напоминания отправляются по номеру из карточки.
  const chatId = phoneOrChatId.includes("@") ? phoneOrChatId : chatIdFromPhone(phoneOrChatId);
  if (!chatId) return { ok: false, error: "Не удалось разобрать номер получателя" };

  const body = text.trim();
  if (!body) return { ok: false, error: "Пустое сообщение" };

  const res = await enqueue(() =>
    call<{ idMessage?: string }>(ENDPOINTS.sendMessage(creds.idInstance, creds.apiToken), {
      chatId,
      // Green API ограничивает длину; режем заранее, чтобы не получить отказ
      // на всём сообщении.
      message: body.slice(0, 4000),
    }),
  );

  if (!res.ok) return { ok: false, error: res.error };
  if (!res.data.idMessage) {
    // Ответ без идентификатора: сообщение могло уйти. Не подтверждаем
    // доставку, но и не отправляем второе — решает человек.
    return { ok: false, error: "Green API не вернул идентификатор сообщения" };
  }
  return { ok: true, externalId: res.data.idMessage };
}

/**
 * Отправить файл пациенту — загрузкой, а не ссылкой (см. ENDPOINTS).
 *
 * Провайдер сам решает, чем показать файл собеседнику, по типу и имени:
 * `voice.ogg` с типом audio/ogg приходит голосовым, jpeg — фотографией.
 * Поэтому имя файла не выдумываем и тип не подменяем.
 *
 * Повторов нет намеренно: обрыв на отправке значит, что файл мог уйти, и
 * повтор пришлёт пациенту второй. Так же устроена и отправка текста.
 */
export async function sendFile(input: {
  companyId: string;
  phoneOrChatId: string;
  bytes: Uint8Array;
  fileName: string;
  mimeType: string;
  caption?: string;
  quotedMessageId?: string | null;
}): Promise<SendResult> {
  if (!isWhatsappEnabled()) return { ok: false, error: "Интеграция WhatsApp выключена" };

  const creds = await loadCredentials(input.companyId);
  if (!creds) return { ok: false, error: "Не заданы ключи Green API" };

  const chatId = input.phoneOrChatId.includes("@")
    ? input.phoneOrChatId
    : chatIdFromPhone(input.phoneOrChatId);
  if (!chatId) return { ok: false, error: "Не удалось разобрать номер получателя" };

  const form = new FormData();
  form.append("chatId", chatId);
  form.append("fileName", input.fileName);
  if (input.caption) form.append("caption", input.caption.slice(0, 1000));
  if (input.quotedMessageId) form.append("quotedMessageId", input.quotedMessageId);
  form.append(
    "file",
    new Blob([new Uint8Array(input.bytes)], { type: input.mimeType }),
    input.fileName,
  );

  const url = `${GREEN_API_BASE}${ENDPOINTS.sendFileByUpload(creds.idInstance, creds.apiToken)}`;
  try {
    const res = await enqueue(async () => {
      const r = await fetch(url, {
        method: "POST",
        body: form,
        // Файл грузится дольше текста: двадцати секунд не хватает даже на
        // фотографию с телефона.
        signal: AbortSignal.timeout(90_000),
      });
      const text = await r.text();
      if (!r.ok) return { ok: false as const, error: describeError(r.status, text), status: r.status };
      try {
        return { ok: true as const, data: JSON.parse(text) as { idMessage?: string } };
      } catch {
        return { ok: false as const, error: "Green API ответил неразборчиво", status: r.status };
      }
    });
    if (!res.ok) return { ok: false, error: res.error };
    if (!res.data.idMessage) {
      // Ответ без идентификатора: файл мог уйти. Второй раз не отправляем.
      return { ok: false, error: "Green API не вернул идентификатор сообщения" };
    }
    return { ok: true, externalId: res.data.idMessage };
  } catch (e) {
    const name = (e as Error).name;
    return {
      ok: false,
      error: name === "TimeoutError" ? "провайдер не ответил вовремя" : "сеть недоступна",
    };
  }
}

/**
 * Ответ на конкретное сообщение пациента.
 *
 * Отдельной функцией, а не полем в sendText: цитата — это другое намерение, и
 * ей нужен идентификатор сообщения, которого у обычной отправки нет.
 */
export async function sendTextReply(
  companyId: string,
  phoneOrChatId: string,
  text: string,
  quotedMessageId: string,
): Promise<SendResult> {
  if (!isWhatsappEnabled()) return { ok: false, error: "Интеграция WhatsApp выключена" };
  const creds = await loadCredentials(companyId);
  if (!creds) return { ok: false, error: "Не заданы ключи Green API" };
  const chatId = phoneOrChatId.includes("@") ? phoneOrChatId : chatIdFromPhone(phoneOrChatId);
  if (!chatId) return { ok: false, error: "Не удалось разобрать номер получателя" };
  const body = text.trim();
  if (!body) return { ok: false, error: "Пустое сообщение" };

  const res = await enqueue(() =>
    call<{ idMessage?: string }>(ENDPOINTS.sendMessage(creds.idInstance, creds.apiToken), {
      chatId,
      message: body.slice(0, 4000),
      quotedMessageId,
    }),
  );
  if (!res.ok) return { ok: false, error: res.error };
  if (!res.data.idMessage) return { ok: false, error: "Green API не вернул идентификатор сообщения" };
  return { ok: true, externalId: res.data.idMessage };
}

/**
 * Удалить своё сообщение у пациента.
 *
 * WhatsApp разрешает это ограниченное время после отправки, и провайдер
 * отвечает отказом, когда срок вышел. Отказ показываем словами: «удалено у
 * нас, но у пациента осталось» — это разные вещи, и человек должен знать, что
 * именно произошло.
 */
export async function deleteMessage(
  companyId: string,
  phoneOrChatId: string,
  idMessage: string,
): Promise<SendResult> {
  if (!isWhatsappEnabled()) return { ok: false, error: "Интеграция WhatsApp выключена" };
  const creds = await loadCredentials(companyId);
  if (!creds) return { ok: false, error: "Не заданы ключи Green API" };
  const chatId = phoneOrChatId.includes("@") ? phoneOrChatId : chatIdFromPhone(phoneOrChatId);
  if (!chatId) return { ok: false, error: "Не удалось разобрать номер получателя" };

  const res = await enqueue(() =>
    call<unknown>(ENDPOINTS.deleteMessage(creds.idInstance, creds.apiToken), { chatId, idMessage }),
  );
  return res.ok ? { ok: true } : { ok: false, error: res.error };
}

/** Сообщение, ждущее отправки в очереди провайдера. */
export interface QueuedMessage {
  /** Идентификатор, который провайдер вернул при постановке (`idMessage`). */
  id: string;
  chatId: string | null;
}

/**
 * Что лежит в очереди исходящих у Green API (первые 500). null — спросить не
 * удалось: интеграция выключена, ключей нет или провайдер не ответил.
 */
export async function messagesQueue(companyId: string): Promise<QueuedMessage[] | null> {
  if (!isWhatsappEnabled()) return null;
  const creds = await loadCredentials(companyId);
  if (!creds) return null;
  const res = await call<unknown>(ENDPOINTS.showMessagesQueue(creds.idInstance, creds.apiToken));
  if (!res.ok || !Array.isArray(res.data)) return null;
  const out: QueuedMessage[] = [];
  for (const row of res.data as Record<string, unknown>[]) {
    const body = (row?.body ?? {}) as Record<string, unknown>;
    const chatId = typeof body.chatId === "string" ? body.chatId : null;
    const ids = typeof row?.messageID === "string" ? [row.messageID] : Array.isArray(row?.messagesIDs) ? row.messagesIDs : [];
    for (const id of ids) if (typeof id === "string" && id) out.push({ id, chatId });
  }
  return out;
}

/** Очистить очередь исходящих целиком — выборочно провайдер не умеет. */
export async function clearMessagesQueue(companyId: string): Promise<boolean> {
  if (!isWhatsappEnabled()) return false;
  const creds = await loadCredentials(companyId);
  if (!creds) return false;
  const res = await call<{ isCleared?: boolean }>(ENDPOINTS.clearMessagesQueue(creds.idInstance, creds.apiToken));
  return res.ok && res.data?.isCleared === true;
}

